            tStart = min(r0.arcLength, r1.arcLength) / refPath.totalLength;
            tEnd   = max(r0.arcLength, r1.arcLength) / refPath.totalLength;
        }

        tStart = min(max(tStart, 0), 1);
        tEnd   = min(max(tEnd,   0), 1);
