                    "side1"             : qUnion([wireAVerts[a], wireAEdgeQ]),
                    "match1"            : match1,
                    "flip1"             : flip1,
                    "side2"             : qUnion([bestBVert, wireBEdgeQ]),
                    "match2"            : match2,
                    "flip2"             : flip2,
                    "method"            : BridgingCurveMethod.CONTROL_POINTS,
                    "editControlPoints" : false
