    // opBoolean UNION merges sheet bodies that share boundary edges.
    // Disconnected surfaces cannot be merged and will throw; the catch leaves
    // them as-is so partially-connected sets still get merged where possible.
    if (definition.returnLoftSurface)
    {
        var surfBodies = evaluateQuery(context, qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SHEET));
        if (size(surfBodies) > 1)
        {
            try
            {
                opBoolean(context, id + "collectSurfs", {
                    "tools"         : qUnion(surfBodies),
                    "operationType" : BooleanOperationType.UNION
                });
            }
            catch {}
        }
        // Name all remaining sheet bodies (one per disconnected region group).
        var finalSurfs = evaluateQuery(context, qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SHEET));
        for (var fi = 0; fi < size(finalSurfs); fi += 1)
        {
            var nm = size(finalSurfs) == 1 ? "variableLoftSurface" : ("variableLoftSurface " ~ (fi + 1));
            setProperty(context, {
                "entities"     : finalSurfs[fi],
                "propertyType" : PropertyType.NAME,
                "value"        : nm
            });
        }
    }

    // --- Collect all wires into as few bodies as possible ---
    // opBoolean UNION on wire bodies merges connected segments; disconnected
    // sets will throw and the catch leaves them as separate wire bodies.
    if (definition.returnOffsetWires)
    {
        var wireBodies = evaluateQuery(context, qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.WIRE));
        if (size(wireBodies) > 1)
        {
            var allWireEdges = qOwnedByBody(qUnion(wireBodies), EntityType.EDGE);
            var wireMade = false;
            try
            {
                opExtractWires(context, id + "collectWires", { "edges" : allWireEdges });
                wireMade = true;
            }
            catch {}
            if (wireMade)
            {
                try
                {
                    opDeleteBodies(context, id + "delOldWires", { "entities" : qUnion(wireBodies) });
                }
                catch {}
            }
        }
    }
}


function surfaceLofter(context is Context, id is Id,
        edgeA is Query, faceA is Query, edgeB is Query, faceB is Query,
        rAContinuity is IntersectionContinuityType, rBContinuity is IntersectionContinuityType)
{
    // Only apply MATCH_TANGENT when the adjacent face is confirmed non-empty.
    // If the face is missing, loft throws LOFT_NO_FACE_FOR_START/END_CLAMP even
    // when auto-detect is attempted -- fall back to G0 for that end instead.
    var useG1A = (rAContinuity == IntersectionContinuityType.G1) && !isQueryEmpty(context, faceA);
    var useG1B = (rBContinuity == IntersectionContinuityType.G1) && !isQueryEmpty(context, faceB);

    var loftDef = {
        "bodyType"               : ExtendedToolBodyType.SURFACE,
        "surfaceOperationType"   : NewSurfaceOperationType.NEW,
        "wireProfilesArray"      : [
            { "wireProfileEntities" : qUnion([edgeA]) },
            { "wireProfileEntities" : qUnion([edgeB]) }
        ],
        "startCondition"         : useG1A ? LoftEndDerivativeType.MATCH_TANGENT : LoftEndDerivativeType.DEFAULT,
        "endCondition"           : useG1B ? LoftEndDerivativeType.MATCH_TANGENT : LoftEndDerivativeType.DEFAULT,
        "trimProfiles"           : false,
        "makePeriodic"           : false,
        "showIsocurves"          : false,
        "defaultSurfaceScope"    : true,
        "addSections"            : false,
        "addGuides"              : false
    };

    if (useG1A)
    {
        loftDef = mergeMaps(loftDef, { "adjacentFacesStart" : faceA, "startMagnitude" : 1.0 });
    }
    if (useG1B)
    {
        loftDef = mergeMaps(loftDef, { "adjacentFacesEnd" : faceB, "endMagnitude" : 1.0 });
    }

    // Try the requested continuity first; if that fails, retry as G0.
    var succeeded = false;
    try
    {
        loft(context, id, loftDef);
        succeeded = true;
    }
    catch {}

    if (!succeeded && (useG1A || useG1B))
    {
        var g0Def = mergeMaps(loftDef, {
            "startCondition" : LoftEndDerivativeType.DEFAULT,
            "endCondition"   : LoftEndDerivativeType.DEFAULT
        });
        loft(context, id + "g0", g0Def);
    }
}

