// --- Editing logic -----------------------------------------------------------

export function generateSWRoutEditingLogic(context is Context, id is Id,
        oldDefinition is map, definition is map, isCreating is boolean,
        specifiedParameters is map, hiddenBodies is Query) returns map
{
    // Migrate legacy fields: regionName -> name, X_EXTENTS -> ALONG_REF
    var migratedRegions = [];
    for (var i = 0; i < size(definition.swRoutRegions); i += 1)
    {
        var reg = definition.swRoutRegions[i];
        if ((reg.name == undefined || reg.name == "") && reg.regionName != undefined)
        {
            reg = mergeMaps(reg, { "name" : reg.regionName });
        }
        if (reg.extentType == undefined)
        {
            reg = mergeMaps(reg, { "extentType" : SWRoutExtentType.ALONG_REF });
        }
        migratedRegions = append(migratedRegions, reg);
    }
    definition.swRoutRegions = migratedRegions;

    if (size(definition.swRoutRegions) > 0)
    {
        var sortedRegions = definition.swRoutRegions;  // fallback: unsorted

        // Only sort when every region's extent inputs are ready.  A QUERY-mode
        // region without two picked points would throw inside processSwRoutRegions
        // -- valid at regen time, but during editing we want the UI to keep working
        // while the user is still filling in picks.
        var allRegionsReady = true;
        for (var reg in definition.swRoutRegions)
        {
            if (reg.extentType == SWRoutExtentType.QUERY)
            {
                if (reg.extentQueries == undefined ||
                        size(evaluateQuery(context, reg.extentQueries)) != 2)
                {
                    allRegionsReady = false;
                    break;
                }
            }
        }

        if (allRegionsReady &&
                !isQueryEmpty(context, definition.refWire) &&
                !isQueryEmpty(context, definition.refWireOrigin))
        {
            var refWirePath = constructPath(context,
                    qOwnedByBody(definition.refWire, EntityType.EDGE));
            var dirSign = (definition.flipRefWire == true) ? -1 : 1;
            // Build a canonical (dirSign=+1) pass purely for ordering: flipRefWire
            // must invert offset sign downstream but must NOT reorder regions or
            // swap user-assigned identities (e.g. "Tip" vs "Tail").
            var canonicalRegions = processSwRoutRegions(context, id + "elSortCanon",
                    definition, refWirePath, definition.refWireOrigin, 1);
            var canonicalOrder = sort(canonicalRegions, function(a, b)
            {
                return ((a.tStart + a.tEnd) / 2) - ((b.tStart + b.tEnd) / 2);
            });
            // Geometric pass uses the actual dirSign for tStart/tEnd values.
            var geomRegions = processSwRoutRegions(context, id + "elSort",
                    definition, refWirePath, definition.refWireOrigin, dirSign);
            sortedRegions = [];
            for (var i = 0; i < size(canonicalOrder); i += 1)
            {
                sortedRegions = append(sortedRegions, geomRegions[canonicalOrder[i].regionNum]);
            }
        }

        var newRegions = [];
        for (var i = 0; i < size(sortedRegions); i += 1)
        {
            var reg = sortedRegions[i];
            reg.regionNum = i;
            var nm = reg.name;
            reg.needsDefaultName = (nm == undefined || nm == "" || startsWith(nm, "Region "));
            if (reg.needsDefaultName) { reg.name = "Region " ~ i; }
            newRegions = append(newRegions, reg);
        }
        definition.swRoutRegions       = newRegions;
        definition.swRoutIntersections = rebuildSwRoutIntersections(definition, newRegions);
    }
    else
    {
        definition.swRoutIntersections = [];
    }

    return definition;
}


